import sys
import types

NS = types.SimpleNamespace


class _MCPServer:
    def __init__(self, name):
        self.name = name

    def tool(self):
        return lambda fn: fn

    def run(self, transport="stdio"):
        print(f"{self.name}: serving MCP over {transport}")


async def _fetch_order(order_id):
    return NS(status="shipped")


class _Response:
    def raise_for_status(self):
        return None

    def json(self):
        return {"status": "shipped"}


class _AsyncClient:
    async def __aenter__(self):
        return self

    async def __aexit__(self, *exc):
        return False

    async def get(self, url, **kwargs):
        return _Response()


sys.modules["mcp"] = types.ModuleType("mcp")
sys.modules["mcp.server"] = NS(MCPServer=_MCPServer)
sys.modules["shop"] = types.ModuleType("shop")
sys.modules["shop.db"] = NS(fetch_order=_fetch_order)
sys.modules["httpx2"] = NS(AsyncClient=_AsyncClient)
